  "词条": "隐海修会",
  "关键词": ["Hidden Sea Society", "Imbratto Worship", "Religious Complex", "Tide Sanctuary", "Fissare Residence", "Society Tower", "Society Garden"],
  "性质": "拉古那城中信奉英白拉多的宗教组织，其建筑群包含多个区域，是岁主信仰的中心",
  "总览": "拉古那城中瞻仰岁主雕像的巨大建筑，包含上下两层，被统称为“隐海修会”。不同于城内的热闹,与城区一水之隔的隐海修会安静且庄重。高大的建筑背靠拂风水畔，从高处俯瞰着拉古那城区。华丽的彩窗、巨大的雕塑、丰富的色彩装饰等,让隐海修会显得庄严而古典，圣洁而肃穆。",
  "分支": {
    "潮汐圣堂": {
      "关键词": ["Tide Sanctuary", "Water Chapel", "Imbratto Statue", "Gondola Access", "Tidal Fluctuations"],
      "描述": "与拉古那城内海联通的水上礼拜堂，岁主的巨像伫立于圣堂之中。修会信仰者们会乘坐贡多拉前往朝拜,并在水面上留下鲜花与水烛台。因圣堂内的水位会伴随着潮汐起落，如同岁主的呼吸所催发了潮汐，故被称作潮汐圣堂。"
    },
    "翡萨烈府邸区": {
      "关键词": ["Fissare Residence Area", "Sky Garden", "Sculptures", "Residential Area"],
      "描述": "翡萨烈家族成员们日常聚集、生活的区域，与修会相连，仿若大型的空中花园,街道上遍布隐海修会的雕塑。"
    },
    "修会塔楼": {
      "关键词": ["Society Tower", "Clerics' Office", "Sculptures", "Watchful Guards"],
      "描述": "隐海修会的教士们办公的塔楼。室内两侧皆伫立着巨大的雕塑,宛若无声的卫兵，注视着每一个来访者。"
    },
      "水星天教堂": {
      "描述": "拉古那城中用以瞻仰岁主雕像的神圣建筑，包含上下两层，被统称为“水星天教堂”，亦是隐海修会之所在"
    },
    "修会花园": {
      "关键词": ["Society Garden", "Water Garden", "Confessional", "Hidden Secret"],
      "描述": "水星天圣堂背后存在一小片水上花园，花园尽头的忏悔室中，说出要惭悔的事物后可以搭乘电梯来到'拂风水畔'"
    }
  },
  "意义": {
    "宗教": "岁主信仰的中心，拉古那的精神象征",
    "文化": "体现了拉古那的宗教文化和建筑艺术",
    "社会": "宗教活动和社会生活的交汇点"
  }
}

